void check(bool b,const char*s){if(!b)throw std::runtime_error(s);}
template<class T>T*child(QObject&p,const char*s){auto*t=dynamic_cast<T*>(p.findChild<QObject*>(s));check(t,s);return t;}
void events(){QApplication::processEvents();QThread::msleep(2);}
void mouseButton(QPushButton&button,bool down){const QPointF local=button.rect().center();QMouseEvent event(down?QEvent::MouseButtonPress:QEvent::MouseButtonRelease,local,button.mapToGlobal(local.toPoint()),Qt::LeftButton,down?Qt::LeftButton:Qt::NoButton,Qt::NoModifier);QApplication::sendEvent(&button,&event);events();}
QPushButton*tab(CandidatePanel&panel,const QString&text){for(auto*button:panel.findChildren<QPushButton*>())if(button->text()==text)return button;throw std::runtime_error("candidate subtab not found");}
void until(const std::function<bool()>&f,const char*s){QElapsedTimer t;t.start();while(!f()&&t.elapsed()<20000)events();check(f(),s);}
