QByteArray bytesAt(const QString&path){QFile f(path);check(f.open(QIODevice::ReadOnly),"read output-protection sentinel");return f.readAll();}
void writeSentinel(const QString&path,const QByteArray&bytes){QFile f(path);check(f.open(QIODevice::WriteOnly)&&f.write(bytes)==bytes.size(),"write isolated output-protection sentinel");}
